import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ACME","description":"","frontmatter":{"title":"ACME","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/acme.md","filePath":"cs/acme.md","lastUpdated":1789023840000}'),h={name:"cs/acme.md"};function A(C,a,E,m,T,_){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="acme" tabindex="-1">ACME <a class="header-anchor" href="#acme" aria-label="Permalink to &quot;ACME&quot;">​</a></h1><div class="epigraph"><p>Let’s Encrypt 把「证明你控制该域名」收成 HTTP-01 / DNS-01 挑战，证书申请从工单变成协议。自动化降低过期，也把挑战实现错误变成新的攻击面。</p><footer>—— RFC 8555；Barnes et al., Automatic Certificate Management Environment</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/certificate-transparency">CT</a>要求证书可被看见。缺口是<strong>谁有资格让 CA 签这张叶</strong>：ACME 用挑战证明控制权，替换人工邮件确认。不重写链验证。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工签发导致过期与弱私钥。ACME：账户密钥、订单、挑战、下载。HTTP-01 在约定路径放令牌；DNS-01 放 TXT。缺口是挑战的绑定：若攻击者能写你的 <code>.well-known</code> 或改你的 DNS，就能申请到证——这是控制面安全，不是 AES 的锅。</p><h3 id="通配与多名字" tabindex="-1">通配与多名字 <a class="header-anchor" href="#通配与多名字" aria-label="Permalink to &quot;通配与多名字&quot;">​</a></h3><p>一张证多个 SAN 要每个都过挑战。通配通常强制 DNS-01。</p><p><span class="marginnote">RFC 8555。Let’s Encrypt 是部署实例，协议不绑一家 CA。本课不提供抢注或劫持挑战的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按账户→订单→挑战→签发走状态机。强调私钥在申请人主机生成，CA 只签公钥。续期同样要过挑战。对照：企业私有 CA 可用同一思想走内部 ACME。</p>',12)),(e(),s(p,null,{default:r(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%B4%A6%E6%88%B7%E9%92%A5%22%5D%20--%3E%20ORD%5B%22%E8%AE%A2%E5%8D%95%20FQDN%22%5D%0A%20%20ORD%20--%3E%20CH%5B%22HTTP-01%20%E6%88%96%20DNS-01%22%5D%0A%20%20CH%20--%3E%20CRT%5B%22CA%20%E7%AD%BE%E5%8F%B6%E8%AF%81%E4%B9%A6%22%5D%0A%20%20CRT%20--%3E%20CT2%5B%22%E4%BB%8D%E5%BA%94%E8%BF%9B%20CT%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份证明从「组织开信」改成「当时能写该名下的资源」。TLS 的保密不自动保护挑战路径：HTTP-01 常先走 80 端口。CAA 记录限制哪些 CA 可签，是另一层政策。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部挑战类型的边界案例。下一课 TLS 攻击史：套件与实现的历史失败，默认假设证书验证与 ACME 已在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CT 看见证书；ACME 证明当时控制该名。</li><li>挑战实现错误等于把签发权交给能写 Web/DNS 的人。</li><li>私钥本地生成；续期仍要挑战。</li><li>下一课：TLS 攻击史当合同对照。</li><li>出处：RFC 8555；Let’s Encrypt 设计叙述；对照 RFC 5280。</li></ul>',8))])}const D=i(h,[["render",A]]);export{f as __pageData,D as default};
